/* Navigation and teaching cues for a first-time learner. */
function firstUnfinishedCourse(){const i=courses.findIndex(c=>!state.completed.includes(c.id));return i<0?courses.length-1:i;}
function beginnerHome(){const next=firstUnfinishedCourse();return `<main class="hub-main"><section class="beginner-start"><div><div class="eyebrow">运维为主线 · 从零开始</div><h1>今天，学会一个能用的操作。</h1><p>第一次来，从 Linux 第 1 课开始。每课先看讲解，再动手验证，最后答一道小测；不用先安装软件，也不用一次记住所有命令。</p><div class="hero-actions"><button class="primary" data-action="lesson" data-id="${next}">${state.completed.length?'继续基础第 '+(next+1)+' 课':'零基础：开始 Linux 第 1 课'}</button><button class="secondary" data-guide="open">第一次使用？看学习指南</button></div><p class="beginner-resume">基础路线已通过 ${state.completed.length}/${courses.length} 课 · 当前可学：${esc(courses[next].title)}</p></div><div class="beginner-path" aria-label="每课学习流程"><div><b>1 · 看懂</b><span>理解场景、语法与示例</span></div><div><b>2 · 动手</b><span>输入、执行，观察真实或模拟结果</span></div><div><b>3 · 确认</b><span>通过校验后手动继续</span></div><div><b>4 · 通关</b><span>答对小测，解锁下一课</span></div></div></section><section class="section"><div class="page-head"><div><h2>运维该按什么顺序学？</h2><p>基础闯关是主线；工作实战补业务场景；排障演练用于独立练习。</p></div><button class="secondary" data-action="view" data-view="roadmap">查看完整基础路线</button></div><div class="concept-flow">${['Linux 与日志','Shell 与自动化','SQL 与数据库','服务与部署','Docker 与 K8s'].map((t,i)=>`<span><small>${i+1}</small>${t}</span>`).join('')}</div><p>如果基础已经熟悉，可进入工作实战，从管道、页面请求一路查到 DM8。遇到具体故障时，再选排障案例。</p><div class="hero-actions"><button class="secondary" data-hub="subject" data-id="ops">查看运维工作实战</button><button class="secondary" data-incident="open" data-id="schema-500">独立排障演练</button></div></section><section class="section"><h2>选择其他课堂</h2><p>每个领域独立记录进度。先选一个持续学习，不必同时开启所有路线。</p><div class="subject-grid">${Object.entries(hubSubjects).filter(([id])=>id!=='ops').map(([id,s])=>`<button class="subject-card ${s.tone}" data-hub="subject" data-id="${id}"><span class="subject-mark">${s.mark}</span><small>${s.tag}</small><h2>${s.name}</h2><p>${s.description}</p><span class="card-link">${id==='python'?pythonLessons.length+' 节可运行代码课':hubCurriculum[id].length+' 节引导课'}</span></button>`).join('')}</div></section><section class="section"><h2>你的练习会保存在哪里？</h2><p>进度与代码草稿保存在当前设备的浏览器中，手机和电脑暂不自动同步。命令、SQL 与排障使用教学模拟；Python 在浏览器运行，教学文件每次运行会重置。清除站点数据会移除本设备记录。</p><button class="text-button" data-hub="books">进入阅读书房</button></section></main>`;}
function learningGuideHTML(){return `<main class="hub-main"><div class="page-head"><div><div class="eyebrow">第一次使用 / 学习指南</div><h1>先完成一课，再继续下一课。</h1><p>你不需要有基础。这是一套“解释 → 练习 → 验证”的学习路线。</p></div><button class="primary" data-action="lesson" data-id="${firstUnfinishedCourse()}">开始基础课堂</button></div><section class="section"><h2>第一次的五个动作</h2><ol class="guide-steps"><li><b>选基础第 1 课。</b>还不会命令就从 Linux 起步，暂时不用选择工作实战或 K8s。</li><li><b>读“什么时候用”和示例。</b>知道这条命令检查什么、参数是什么意思、结果能说明什么。</li><li><b>点击“我读懂了，开始练习”。</b>在练习区输入当前步骤要求的命令；可以先填入标准示例，再读每一部分。</li><li><b>执行后看结果，再确认。</b>执行成功与完成任务是两回事。只有校验通过，“确认结果”按钮才可点击。</li><li><b>回答小测并检查答案。</b>选答案不会自动跳关；答对后手动点击下一课。答错就回看讲解，修改再检查。</li></ol></section><section class="section"><h2>不清楚下一步时，看这里</h2><div class="guide-table"><div><b>还不能进入操作</b><p>先看理解页，再点击“我读懂了”。</p></div><div><b>代码或命令报错</b><p>读错误类型、路径和行号；对照本步示例修改，不用反复点下一步。</p></div><div><b>运行了但没有通过</b><p>结果还不符合当前任务。核对对象、条件、变量和预期结果。</p></div><div><b>已经验证通过</b><p>先读懂输出，再点“确认结果”；完成全部操作后进入小测。</p></div><div><b>换答案后通过状态消失</b><p>新答案需要重新检查，网站不会沿用旧答案的通过状态。</p></div><div><b>刷新或换设备</b><p>同一浏览器可继续保存的进度；另一台设备不会自动接着学。</p></div></div></section><section class="section"><h2>几条路线有什么区别？</h2><ul><li><b>基础闯关：</b>从 Linux、Shell、SQL 逐步到部署、容器与 K8s，适合从零开始。</li><li><b>工作实战：</b>把工具连接成业务调查链路，重点是日志定位和 DM8。</li><li><b>排障演练：</b>三个案例可以独立进入，先拿证据再判断，不代替基础课程。</li><li><b>Python 课堂：</b>先学代码基础，再处理教学日志和生成巡检摘要。</li></ul><p>建议一次 20–30 分钟，以能解释自己做了什么为目标；课程数量不是熟练度。学完后在个人测试环境复做，逐渐迁移到实际工作。</p></section></main>`;}
hubHome=beginnerHome;
const guideBaseRender=render,guideBaseNav=hubNav,guideBaseCourse=hubCourseHTML,guideBaseClassroom=classroom;
hubNav=function(){return guideBaseNav().replace('</nav>','<button data-guide="open" '+(view==='guide'?'aria-current="page"':'')+'>学习指南</button></nav>');};
function flowCue(phase,title){const cues={learn:['现在：看懂这一课','下一步：读完场景与示例，点击“我读懂了，开始练习”。'],practice:['现在：完成当前操作','下一步：先执行并验证；通过后读输出，再点击“确认结果”。'],quiz:['现在：检查理解','下一步：选择答案并检查；答对后手动进入下一课。']};const cue=cues[phase]||cues.learn;return `<div class="flow-cue" role="note"><b>${cue[0]}</b><span>本课目标：${esc(title)}</span><span>${cue[1]}</span></div>`;}
hubCourseHTML=function(){let html=guideBaseCourse();const c=activeHubLesson();html=html.replace('<div class="learning-tabs"',flowCue(hubPhase,c.summary)+'<div class="learning-tabs"');const t=c.tasks[hubAttempt.step];return html.replace('执行 / 验证本步',t?.type==='command'?'执行命令并验证':'检查本步答案');};
classroom=function(){return guideBaseClassroom().replace('<div class="meta">',flowCue(learningTab,current().summary)+'<div class="meta">');};
render=function(){if(view==='guide'){$('app').innerHTML=hubNav()+learningGuideHTML();return;}return guideBaseRender();};
document.addEventListener('click',e=>{const guide=e.target.closest('[data-guide]');if(guide){view='guide';render();window.scrollTo({top:0,behavior:'instant'});return;}const hub=e.target.closest('[data-hub]'),base=e.target.closest('[data-action]');if(hub&&['read','phase','next','confirm-task'].includes(hub.dataset.hub)||base&&['read-done','advance-step','next','learning-tab'].includes(base.dataset.action))setTimeout(()=>document.querySelector('main')?.scrollIntoView({block:'start',behavior:'instant'}),0);});
const guideBaseTask=taskHTML;
taskHTML=function(){return guideBaseTask().replace(/<button class="primary advance-step" data-action="advance-step"[^>]*>[\s\S]*?<\/button>/,'<p class="small-note">请在“交互练习区”查看输出并确认结果，下一步按钮在那里。</p>');};
render();
